css:
.cultneg-sim-container {
    padding: 24px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.cultneg-sim-header {
    background: #1a2744;
    color: #f4f5f7;
    padding: 28px 32px;
    border-radius: 4px;
    margin-bottom: 24px;
    border-left: 6px solid #c9a55b;
}
.cultneg-sim-title-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
}
.cultneg-sim-header h1 {
    font-size: 1.4rem;
    font-weight: 600;
    margin: 0;
    letter-spacing: 0.02em;
    color: #ffffff;
}
.cultneg-sim-period-badge {
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(201,165,91,0.4);
    color: #c9a55b;
    padding: 8px 16px;
    border-radius: 4px;
    font-size: 0.85rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    font-weight: 600;
}
.cultneg-sim-subtitle-row {
    margin-top: 16px;
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}
.cultneg-sim-tag {
    background: rgba(201,165,91,0.15);
    color: #c9a55b;
    border: 1px solid rgba(201,165,91,0.35);
    padding: 6px 12px;
    border-radius: 3px;
    font-size: 0.78rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-weight: 600;
}
.cultneg-sim-tag-secondary {
    background: rgba(255,255,255,0.06);
    color: #d8dde6;
    border-color: rgba(255,255,255,0.18);
}
.cultneg-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.cultneg-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d9dde4;
    border-radius: 4px;
    padding: 18px 16px;
    border-top: 3px solid #1a2744;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.cultneg-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(26,39,68,0.08);
}
.cultneg-sim-kpi-card.cultneg-sim-japan { border-top-color: #c41e3a; }
.cultneg-sim-kpi-card.cultneg-sim-germany { border-top-color: #1a2744; }
.cultneg-sim-kpi-card.cultneg-sim-brazil { border-top-color: #2d6a4f; }
.cultneg-sim-kpi-card.cultneg-sim-protocol { border-top-color: #c9a55b; }
.cultneg-sim-kpi-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
    font-weight: 600;
}
.cultneg-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #1a2744;
}
.cultneg-sim-scenario {
    background: #ffffff;
    border: 1px solid #d9dde4;
    border-left: 4px solid #c9a55b;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.cultneg-sim-scenario-header h3 {
    font-size: 1.1rem;
    color: #1a2744;
    margin: 0 0 12px 0;
    font-weight: 600;
}
.cultneg-sim-scenario-body {
    color: #2c3a52;
    font-size: 0.95rem;
    line-height: 1.65;
}
.cultneg-sim-scenario-body em {
    font-style: italic;
    color: #5a6477;
}
.cultneg-sim-controls {
    background: #ffffff;
    border: 1px solid #d9dde4;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.cultneg-sim-controls h3 {
    font-size: 0.95rem;
    color: #1a2744;
    margin: 0 0 18px 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 600;
}
.cultneg-sim-controls label {
    color: #6b7280;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
    font-weight: 600;
    display: block;
}
.cultneg-sim-controls select,
.cultneg-sim-controls input[type="number"],
.cultneg-sim-controls input[type="text"] {
    background: #ffffff;
    border: 1px solid #c1c7d1;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.9rem;
    margin-bottom: 16px;
    font-family: inherit;
}
.cultneg-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.cultneg-sim-controls select:focus,
.cultneg-sim-controls input:focus {
    outline: none;
    border-color: #c9a55b;
    box-shadow: 0 0 0 3px rgba(201,165,91,0.15);
}
.cultneg-sim-actions {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}
.cultneg-sim-controls .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    color: #ffffff;
    padding: 10px 24px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-size: 0.82rem;
    border-radius: 3px;
}
.cultneg-sim-controls .btn-primary:hover {
    background: #243456;
    border-color: #243456;
}
.cultneg-sim-controls .btn-outline-secondary {
    color: #6b7280;
    border-color: #c1c7d1;
    padding: 10px 18px;
    font-size: 0.78rem;
    border-radius: 3px;
    background: #ffffff;
}
.cultneg-sim-controls .btn-outline-secondary:hover {
    background: #f4f5f7;
    color: #1a2744;
    border-color: #6b7280;
}
.cultneg-sim-history {
    background: #ffffff;
    border: 1px solid #d9dde4;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.cultneg-sim-history table {
    margin: 0;
    font-size: 0.85rem;
    color: #2c3a52;
    width: 100%;
}
.cultneg-sim-history table th {
    background: #f4f5f7;
    color: #1a2744;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.06em;
    border-bottom: 2px solid #c9a55b;
    padding: 10px 8px;
}
.cultneg-sim-history table td {
    padding: 8px;
    border-top: 1px solid #e5e8ed;
}
.cultneg-sim-chart {
    background: #ffffff;
    border: 1px solid #d9dde4;
    border-radius: 4px;
    padding: 24px;
    height: 380px;
}
@media (max-width: 768px) {
    .cultneg-sim-container { padding: 16px; }
    .cultneg-sim-header { padding: 20px; }
    .cultneg-sim-header h1 { font-size: 1.15rem; }
    .cultneg-sim-kpi-value { font-size: 1.6rem; }
    .cultneg-sim-scenario, .cultneg-sim-controls, .cultneg-sim-history { padding: 18px; }
    .cultneg-sim-chart { height: 320px; padding: 16px; }
    .cultneg-sim-actions { flex-direction: column; }
    .cultneg-sim-actions .btn { width: 100%; }
}

