(function() {
    'use strict';

    class CulturalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Cultural Distance in Negotiation';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    mitsuyama: 25,
                    hartmann: 80,
                    aramburu: 70,
                    culturalFidelity: 50,
                    ceoConfidence: 50,
                    cfoCostScore: 50,
                    protocolScore: 30,
                    mitsuyamaHistory: [],
                    hartmannHistory: [],
                    aramburuHistory: [],
                    fidelityHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { choice: 'b' };
            }
            var self = this;
            self._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var sel = document.getElementById('choiceSelect');
            if (sel) decisions.choice = sel.value;
            if (!decisions.choice) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('choice_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var choice = state.decisions.choice;
            var deltas = this._getDelta(period, choice);
            var clamp = function(x) { return Math.max(0, Math.min(100, x)); };

            state.domainState.mitsuyama = clamp(state.domainState.mitsuyama + (deltas.mitsuyama || 0));
            state.domainState.hartmann = clamp(state.domainState.hartmann + (deltas.hartmann || 0));
            state.domainState.aramburu = clamp(state.domainState.aramburu + (deltas.aramburu || 0));
            state.domainState.culturalFidelity = clamp(state.domainState.culturalFidelity + (deltas.cultFid || 0));
            state.domainState.ceoConfidence = clamp(state.domainState.ceoConfidence + (deltas.ceoConf || 0));
            state.domainState.cfoCostScore = clamp(state.domainState.cfoCostScore + (deltas.cfoCost || 0));
            state.domainState.protocolScore = clamp(state.domainState.protocolScore + (deltas.protocol || 0));

            state.domainState.mitsuyamaHistory.push(state.domainState.mitsuyama);
            state.domainState.hartmannHistory.push(state.domainState.hartmann);
            state.domainState.aramburuHistory.push(state.domainState.aramburu);
            state.domainState.fidelityHistory.push(state.domainState.culturalFidelity);

            var self = this;
            /* v1.1.0: removed racy setTimeout N+2 desync; panel refreshes on the real period:submitted / period:undone events wired in setupUI. */

            return {
                period: period,
                choice: choice,
                choiceLabel: window.mySimulation.t('p' + period + '_' + choice + '_short'),
                mitsuyama: state.domainState.mitsuyama,
                hartmann: state.domainState.hartmann,
                aramburu: state.domainState.aramburu,
                culturalFidelity: state.domainState.culturalFidelity,
                ceoConfidence: state.domainState.ceoConfidence,
                cfoCostScore: state.domainState.cfoCostScore,
                protocolScore: state.domainState.protocolScore
            };
        }

        _getDelta(period, choice) {
            var TABLE = {
                1: { a: { mitsuyama: -15, cultFid: -10, ceoConf: -5, protocol: -5 },
                     b: { mitsuyama: 5,  cultFid: 15, ceoConf: 10, protocol: 5 },
                     c: { mitsuyama: -20, cultFid: -15, ceoConf: -10 } },
                2: { a: { hartmann: -15, cultFid: -10, ceoConf: -5 },
                     b: { hartmann: 5,  cultFid: 15, ceoConf: 10, protocol: 5 },
                     c: { hartmann: -10, cultFid: -10 } },
                3: { a: { aramburu: -15, cultFid: -10, ceoConf: -5 },
                     b: { aramburu: -5, cultFid: -5 },
                     c: { aramburu: 5,  cultFid: 15, ceoConf: 10, protocol: 5 } },
                4: { a: { mitsuyama: -25, cultFid: -15, ceoConf: -10 },
                     b: { mitsuyama: 30, cultFid: 20, ceoConf: 10, protocol: 10 },
                     c: { mitsuyama: -15, cultFid: -5, ceoConf: -10, cfoCost: -5 } },
                5: { a: { hartmann: -25, cultFid: -15, ceoConf: -10 },
                     b: { hartmann: 10, cultFid: 15, ceoConf: 10, protocol: 10 },
                     c: { hartmann: -15, cultFid: -5, ceoConf: -5 } },
                6: { a: { aramburu: -25, cultFid: -15, ceoConf: -10 },
                     b: { aramburu: 20, cultFid: 20, ceoConf: 10, protocol: 10 },
                     c: { aramburu: -10, cultFid: -5 } },
                7: { a: { protocol: 0,   ceoConf: -10, cultFid: -15, cfoCost: 30 },
                     b: { protocol: -10, ceoConf: -5,  cultFid: 5,   cfoCost: -30 },
                     c: { protocol: 30,  ceoConf: 20,  cultFid: 20,  cfoCost: 10 } },
                8: { a: { cfoCost: 20, cultFid: -20, protocol: -15, ceoConf: -5 },
                     b: { cfoCost: 5,  cultFid: 10,  protocol: 20,  ceoConf: 15 },
                     c: { cfoCost: 10, cultFid: 0,   protocol: 5 } },
                9: { a: { protocol: -15, cultFid: -15, ceoConf: -10 },
                     b: { protocol: 20,  cultFid: 15,  ceoConf: 15 },
                     c: { protocol: -10, cultFid: 5,   cfoCost: -20 } }
            };
            return (TABLE[period] && TABLE[period][choice]) || {};
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('mitsuyamaDisplay', 'domainState.mitsuyama', (v) => Math.round(v) + '%');
            uiManager.bind('hartmannDisplay',  'domainState.hartmann',  (v) => Math.round(v) + '%');
            uiManager.bind('aramburuDisplay',  'domainState.aramburu',  (v) => Math.round(v) + '%');
            uiManager.bind('fidelityDisplay',  'domainState.culturalFidelity', (v) => Math.round(v));
            uiManager.bind('ceoDisplay',       'domainState.ceoConfidence',    (v) => Math.round(v));
            uiManager.bind('cfoDisplay',       'domainState.cfoCostScore',     (v) => Math.round(v));
            uiManager.bind('protocolDisplay',  'domainState.protocolScore',    (v) => Math.round(v));


            if (!this._wired) {
                var _self = this;
                var _refresh = function() { try { _self._updateBriefing(window.mySimulation.state); } catch (e) {} };
                var _sim = window.mySimulation;
                if (_sim && _sim.eventBus && typeof _sim.eventBus.on === 'function') {
                    _sim.eventBus.on('period:submitted', _refresh);
                    _sim.eventBus.on('period:undone', _refresh);
                }
                document.addEventListener('express:langchanged', _refresh);
                this._wired = true;
            }
        }

        getChartConfig() {
            return {
                dealChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Mitsuyama (Japan)', data: [], borderColor: '#c41e3a', backgroundColor: 'rgba(196,30,58,0.08)', borderWidth: 2.5, fill: false, tension: 0.2 },
                            { label: 'Hartmann-Schreiber (Germany)', data: [], borderColor: '#1a2744', backgroundColor: 'rgba(26,39,68,0.08)', borderWidth: 2.5, fill: false, tension: 0.2 },
                            { label: 'Aramburu (Brazil)', data: [], borderColor: '#2d6a4f', backgroundColor: 'rgba(45,106,79,0.08)', borderWidth: 2.5, fill: false, tension: 0.2 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Deal-survival probability (%)', font: { size: 14, weight: '600' }, color: '#1a2744' },
                            legend: { position: 'bottom', labels: { color: '#1a2744', usePointStyle: true } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, grid: { color: '#e5e8ed' }, ticks: { color: '#6b7280' } },
                            x: { grid: { color: '#e5e8ed' }, ticks: { color: '#6b7280' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.mitsuyamaHistory.map((_, i) => 'P' + (i + 1));
            return {
                dealChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.mitsuyamaHistory },
                        { data: state.domainState.hartmannHistory },
                        { data: state.domainState.aramburuHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = (last && last.domainState) || {};
            var mit = ds.mitsuyama || 0;
            var har = ds.hartmann || 0;
            var ara = ds.aramburu || 0;
            var fid = ds.culturalFidelity || 0;
            var protocol = ds.protocolScore || 0;
            var ceo = ds.ceoConfidence || 0;
            var avgProb = (mit + har + ara) / 3;

            var perf = 'Beginner';
            if (avgProb > 60 && fid > 60 && protocol > 60) perf = 'Good';
            if (avgProb > 75 && fid > 75 && protocol > 75) perf = 'Excellent';

            var insights = [];
            if (mit < 40) insights.push('Mitsuyama slipped. The high-context Japanese counterparty needed structured listening, not contractual specificity.');
            if (har < 60) insights.push('Hartmann drifted. Low-context engagement requires matching redline density and hitting the deadline.');
            if (ara < 50) insights.push('Aramburu cooled. Verification is structured warmth, not 78-page redlines and not passive waiting.');
            if (fid < 50) insights.push('Cultural fidelity is low. Hofstede / Meyer / Brett are priors that update with individual evidence.');
            if (protocol < 60) insights.push('Protocol coverage is thin. One global protocol with mandatory country annexes dominates the operating-cost vs pipeline-protection frontier.');
            if (avgProb > 70 && fid > 70 && protocol > 70) insights.push('Strong cross-cultural protocol design. Same deal, three cultures, one architecture with three calibrations.');
            if (ceo > 70 && protocol > 70) insights.push('Board-ready. The recommendation will survive CEO, CFO and Country-GM scrutiny.');

            return {
                mitsuyama: mit,
                hartmann: har,
                aramburu: ara,
                avgProbability: avgProb,
                culturalFidelity: fid,
                protocolScore: protocol,
                ceoConfidence: ceo,
                performance: perf,
                insights: insights
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            if (ds.mitsuyama < 25) return window.mySimulation.t('hint_japan_lost');
            if (ds.hartmann < 50) return window.mySimulation.t('hint_germany_drift');
            if (ds.aramburu < 40) return window.mySimulation.t('hint_brazil_cool');
            if (ds.culturalFidelity < 40) return window.mySimulation.t('hint_low_fidelity');
            if (ds.protocolScore > 70 && state.currentPeriod > 6) return window.mySimulation.t('hint_protocol_strong');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.choiceLabel', label: 'Decision', i18nKey: 'col_decision' },
                { key: 'results.mitsuyama',   label: 'Japan',    i18nKey: 'col_japan',    formatter: (v) => Math.round(v) + '%' },
                { key: 'results.hartmann',    label: 'Germany',  i18nKey: 'col_germany',  formatter: (v) => Math.round(v) + '%' },
                { key: 'results.aramburu',    label: 'Brazil',   i18nKey: 'col_brazil',   formatter: (v) => Math.round(v) + '%' },
                { key: 'results.culturalFidelity', label: 'Fidelity', i18nKey: 'col_fidelity', formatter: (v) => Math.round(v) },
                { key: 'results.protocolScore',    label: 'Protocol', i18nKey: 'col_protocol', formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            if (period > 9) period = 9;
            if (period < 1) period = 1;
            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };

            var phaseEl = document.getElementById('phaseLabel');
            var partyEl = document.getElementById('counterpartyLabel');
            var titleEl = document.getElementById('scenarioTitle');
            var brEl    = document.getElementById('briefingText');
            var sel     = document.getElementById('choiceSelect');

            var phaseKey = period <= 3 ? 'phase_diagnose' : (period <= 6 ? 'phase_design' : 'phase_defend');
            var partyKeys = ['mitsuyama', 'hartmann', 'aramburu', 'mitsuyama', 'hartmann', 'aramburu', 'meta_ceo', 'meta_cfo', 'meta_gm'];
            var partyKey = 'party_' + partyKeys[period - 1];

            if (phaseEl) phaseEl.textContent = t(phaseKey);
            if (partyEl) partyEl.textContent = t(partyKey);
            if (titleEl) titleEl.textContent = t('p' + period + '_title');
            if (brEl)    brEl.innerHTML = t('p' + period + '_brief');

            if (sel) {
                var current = sel.value;
                sel.innerHTML = '';
                ['a', 'b', 'c'].forEach(function(opt) {
                    var o = document.createElement('option');
                    o.value = opt;
                    o.textContent = t('p' + period + '_' + opt);
                    sel.appendChild(o);
                });
                sel.value = current && ['a','b','c'].indexOf(current) >= 0 ? current : 'b';
            }
        }

        getTranslations() {
            return {
                en: {
                    title: `Cultural Distance in Negotiation — Same Deal, Three Cultures`,
                    period_label: `Round`,
                    period_of: `of`,
                    phase_label: `Phase`,
                    counterparty_label: `Counterparty`,
                    scenario_label: `Scenario`,
                    choice_label: `Your move`,
                    submit_btn: `Commit decision`,
                    undo_btn: `Undo last decision`,
                    decisions_heading: `Negotiation Pod — Working Decision`,
                    kpi_japan: `Mitsuyama (Japan)`,
                    kpi_germany: `Hartmann (Germany)`,
                    kpi_brazil: `Aramburu (Brazil)`,
                    kpi_fidelity: `Cultural fidelity`,
                    kpi_ceo: `CEO confidence`,
                    kpi_cfo: `CFO cost score`,
                    kpi_protocol: `Protocol coverage`,
                    phase_diagnose: `Round 1 — Diagnose`,
                    phase_design: `Round 2 — Design`,
                    phase_defend: `Round 3 — Defend`,
                    party_mitsuyama: `Mitsuyama Trust Bank — Tokyo`,
                    party_hartmann: `Hartmann-Schreiber Maschinenbau — Stuttgart`,
                    party_aramburu: `Grupo Aramburu Varejo — São Paulo`,
                    party_meta_ceo: `Andrés Quintero — CEO`,
                    party_meta_cfo: `CFO — Cost defence`,
                    party_meta_gm: `Country GMs — Federation question`,
                    choice_warning: `Pick an option before committing the decision`,
                    col_decision: `Move`,
                    col_japan: `Japan %`,
                    col_germany: `Germany %`,
                    col_brazil: `Brazil %`,
                    col_fidelity: `Fidelity`,
                    col_protocol: `Protocol`,
                    hint_japan_lost: `Mitsuyama is on the brink. Re-read Aoki-san — high-context, ringi-sho consensus, slow listening over fast specs.`,
                    hint_germany_drift: `Hartmann is drifting. Low-context engagement IS engagement — match redline density and hit the Wednesday deadline.`,
                    hint_brazil_cool: `Aramburu is cooling. Verification is structured warmth — long lunch, founder presence, no 78-page contract.`,
                    hint_low_fidelity: `Cultural fidelity is low. The frame is a prior, not a script. Update with individual evidence on every counterparty.`,
                    hint_protocol_strong: `Protocol architecture is converging. Hold the federation discipline through the CFO and Country-GM defences.`,

                    p1_title: `06:14 Madrid — Aoki-san emails from Tokyo`,
                    p1_brief: `Aoki-san writes that the proposal is being given serious consideration and that Compliance and IT Security raised clarifying questions. Yumi appends in red: <em>I read this as a polite signal that the deal is at material risk.</em><br><br>Eight of eleven hanko obtained. Three remaining (Compliance, IT Security, Risk). Eleven weeks elapsed.<br><br><strong>How do you read the email?</strong>`,
                    p1_a: `A. Routine progress update — keep doing what we are doing`,
                    p1_b: `B. Polite signal of material risk — call Yumi, prepare a recovery move`,
                    p1_c: `C. Demand for technical answers — send compliance specs by tomorrow`,
                    p1_a_short: `R1 Japan: routine read`,
                    p1_b_short: `R1 Japan: polite-warning read`,
                    p1_c_short: `R1 Japan: technical-demand read`,

                    p2_title: `Friday — 78 pages of redlines from Stuttgart`,
